with metrics as (select *, sum(duration_sec) over (order by cast(event_time as bigint) range between 604800 preceding and current row) as duration_sec_sum_7d, lag(duration_sec, 2) over w_part as prev_duration_sec from web_events window w_part as (partition by event_type order by event_time, id)), with_dims as (select src.*, d.browser from metrics src left join sessions d on src.session_id = d.id where d.device <> 'tablet'), with_windows as (select id, event_type, page, event_time, sum(duration_sec_sum_7d) over (partition by page, session_id order by duration_sec, id rows between 2 preceding and current row) as last3_sum_duration_sec_sum_7d, min(duration_sec_sum_7d) over (partition by page, session_id order by duration_sec, id rows between 2 preceding and current row) as last3_min_duration_sec_sum_7d, count(duration_sec_sum_7d) over (partition by page, session_id order by duration_sec, id rows between 2 preceding and current row) as last3_count_duration_sec_sum_7d from with_dims), latest as (select *, row_number() over (partition by page order by last3_sum_duration_sec_sum_7d nulls last, id) as rank_in_group from with_windows qualify rank_in_group = 1), gaps as (select *, case when event_time - lag(event_time) over (partition by page order by event_time, id) > interval '14' day then 1 else 0 end as is_new_session from latest), sessionized as (select *, sum(is_new_session) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_no from gaps) select case when last3_count_duration_sec_sum_7d >= 14 then 'HIGH' else 'LOW' end as last3_count_duration_sec_sum_7d_tier, (unix_timestamp(max(event_time)) - unix_timestamp(min(event_time))) / 60 as duration_min, max(event_time) as last_event_time, size(collect_set(event_type)) as num_event_types, count(*) as event_count, approx_percentile(last3_min_duration_sec_sum_7d, array(0.25, 0.5, 0.75)) as last3_min_duration_sec_sum_7d_quartiles from sessionized group by case when last3_count_duration_sec_sum_7d >= 14 then 'HIGH' else 'LOW' end order by num_event_types desc
